private static void writeAgentJar(Path agentJar) throws IOException {
    Manifest mf = new Manifest();
    mf.getMainAttributes().putValue("Manifest-Version", "1.0");
    mf.getMainAttributes().putValue("Agent-Class", "net.montoyo.wd.agent.GlfwStubAgent");
    Path tmp = agentJar.resolveSibling(agentJar.getFileName() + ".tmp");
    try (OutputStream os = Files.newOutputStream(tmp, new OpenOption[0]);
         JarOutputStream jar = new JarOutputStream(os, mf);){
        GlfwStubInjector.putEntry(jar, "org/lwjgl/glfw/GLFW.class", GlfwStubInjector.generateGlfwStub());
        GlfwStubInjector.putEntry(jar, "net/montoyo/wd/agent/GlfwStubAgent.class", GlfwStubInjector.readOwnClass("net/montoyo/wd/agent/GlfwStubAgent.class"));
        GlfwStubInjector.putEntry(jar, "net/montoyo/wd/agent/WdAttachMain.class", GlfwStubInjector.readOwnClass("net/montoyo/wd/agent/WdAttachMain.class"));
    }
    try {
        Files.move(tmp, agentJar, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
    }
    catch (AtomicMoveNotSupportedException e) {
        Files.move(tmp, agentJar, StandardCopyOption.REPLACE_EXISTING);
    }
}

