void ensureBrowser() {
    if (this.closed || this.browser != null || this.browserRequested || !ServerCefManager.isReady()) {
        return;
    }
    this.browserRequested = true;
    ServerCefManager.submit(() -> {
        try {
            CefClient client = ServerCefManager.getCefClient();
            if (client == null || this.closed) {
                this.browserRequested = false;
                return;
            }
            ServerCefManager.installPopupRedirect(client);
            ServerCefManager.installCrashRecovery(client);
            ServerScreenBrowser b = new ServerScreenBrowser(client, this.url, this.browserW, this.browserH, ServerCefManager.createRequestContext());
            b.setCloseAllowed();
            b.createImmediately();
            this.browser = b;
            this.browserCreatedMs = System.currentTimeMillis();
            this.lastInputMs = 0L;
            this.keyframeNeeded = true;
            Log.info("Created server-side browser for screen %s (%dx%d)", this.key, this.browserW, this.browserH);
            if (this.closed) {
                b.closeBrowser();
            }
        }
        catch (Throwable t) {
            Log.errorEx("Failed to create server-side browser for " + this.key, t, new Object[0]);
        }
    });
}

