void startEncoding() {
    if (this.encodeStarted) {
        return;
    }
    this.encodeStarted = true;
    int fps = Math.max(1, CommonConfig.Stream.streamFps);
    this.encodePeriodNs = 1000000000L / (long)fps;
    this.encodeTask = ServerBrowserManager.encodePool().schedule(this::runEncodeTick, 0L, TimeUnit.NANOSECONDS);
}

private void runEncodeTick() {
    int status = this.encodeTick();
    if (this.closed || this.encodeBroken) {
        return;
    }
    long delay = switch (status) {
        case 0 -> Math.max(3000000L, this.nextAllowedNs - 6000000L - System.nanoTime());
        case 1 -> 3000000L;
        default -> this.encodePeriodNs;
    };
    this.encodeTask = ServerBrowserManager.encodePool().schedule(this::runEncodeTick, delay, TimeUnit.NANOSECONDS);
}

void close() {
    this.closed = true;
    if (this.encodeTask != null) {
        this.encodeTask.cancel(false);
        this.encodeTask = null;
    }
    ServerBrowserManager.encodePool().execute(() -> {
        Object object = this.encoderLock;
        synchronized (object) {
            if (this.encoder != null) {
                this.encoder.close();
                this.encoder = null;
            }
        }
    });
    ServerScreenBrowser b = this.browser;
    this.browser = null;
    if (b != null) {
        ServerCefManager.submit(b::closeBrowser);
    }

