package net.montoyo.wd.client.stream;

import com.cinemamod.mcef.MCEFBrowser;
import net.montoyo.wd.WebDisplays;
import net.montoyo.wd.core.IScreenStream;
import net.montoyo.wd.entity.ScreenBlockEntity;
import net.montoyo.wd.entity.ScreenData;
import net.montoyo.wd.utilities.browser.InWorldQueries;
import net.montoyo.wd.utilities.browser.WDBrowser;
import org.cef.browser.CefBrowser;

public class LocalScreenStream
implements IScreenStream {
    private final CefBrowser browser;
    private boolean closed = false;

    public LocalScreenStream(ScreenBlockEntity be, ScreenData scr) {
        String url = WebDisplays.applyBlacklist(scr.url != null ? scr.url : "https://www.google.com");
        CefBrowser cefBrowser = this.browser = WDBrowser.createBrowser(url, false);
        if (cefBrowser instanceof MCEFBrowser) {
            MCEFBrowser mcefBrowser = (MCEFBrowser)cefBrowser;
            if (scr.rotation != null && scr.rotation.isVertical) {
                mcefBrowser.resize(scr.resolution.y, scr.resolution.x);
            } else {
                mcefBrowser.resize(scr.resolution.x, scr.resolution.y);
            }
            mcefBrowser.setCursorChangeListener(type -> {
                scr.mouseType = type;
            });
        }
        if ((cefBrowser = this.browser) instanceof WDBrowser) {
            WDBrowser wdBrowser = (WDBrowser)cefBrowser;
            InWorldQueries.attach(be, scr.side, wdBrowser);
        }
    }

    public MCEFBrowser getBrowser() {
        MCEFBrowser mcefBrowser;
        CefBrowser cefBrowser = this.browser;
        return cefBrowser instanceof MCEFBrowser ? (mcefBrowser = (MCEFBrowser)cefBrowser) : null;
    }

    public void loadURL(String url) {
        if (!this.closed) {
            this.browser.loadURL(url);
        }
